    % colors = {'#000000','#d73989','#e8b6ae','#f0c1ad','#eed0ba','#ebdec6','#cdc0d6','#b8b1cf','#959bad','#97aeb8','#a5bcc1','#b2c9c9','#9ac7a8','#b8dbc9','#c5e3d2','#d1ebdb','#d6e1c8','#e5c28c','#e8d097','#edd9aa','#f2e6bb','#f9f3dd'};
    colors = {'#2bd19a','#bc5090','#ff6361','#ffa600','#1346c7','#2a5ace','#406cd4','#567edb','#6c91e1','#81a3e8','#97b6ee','#adc8f5'};

    subplot(1,2,1)
    plot(paramARR,imag(omegaBG(:,j)),'s','linewidth',1,'MarkerSize',5); hold on
    plot(paramARR,imag(omegaAApprox(:,j)),'.','linewidth',1,'MarkerSize',8); 
